#include <cuda_runtime.h>
#include <cuda.h>
#include <cassert>

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    if (row < N && col < N) {
        float sum = 0.0f;
        for (int k = 0; k < N; k++) {
            sum += A[row * N + k] * B[k * N + col];
        }
        C[row * N + col] = sum;
    }
}

torch::Tensor matmul_forward_cuda(torch::Tensor A, torch::Tensor B) {
    // Check inputs
    assert(A.dim() == 2);
    assert(B.dim() == 2);
    assert(A.size(1) == B.size(0));

    int N = A.size(0);
    int M = B.size(1);

    // Create output tensor
    auto C = torch::zeros({N, M}, A.options());

    // Kernel launch parameters
    dim3 threads(16, 16);
    dim3 blocks((M + threads.x - 1) / threads.x, (N + threads.y - 1) / threads.y);

    // Launch kernel
    matmul_kernel<<<blocks, threads>>>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), N);

    // Check for kernel launch errors
    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        printf("Error in matmul_kernel: %s\n", cudaGetErrorString(err));
        throw std::runtime_error("CUDA kernel launch failed");
    }

    // Synchronize to check for execution errors
    err = cudaDeviceSynchronize();
    if (err != cudaSuccess) {
        printf("Error after kernel execution: %s\n", cudaGetErrorString(err));
        throw std::runtime_error("CUDA kernel execution failed");
